package com.rohit.inventory.controller;
import com.rohit.inventory.dto.request.*; import com.rohit.inventory.dto.response.*; import com.rohit.inventory.entity.StockTransferStatus; import com.rohit.inventory.service.TransferService; import jakarta.validation.Valid; import java.util.*; import org.springframework.data.domain.*; import org.springframework.data.web.PageableDefault; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.security.core.userdetails.UserDetails; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/transfers") public class TransferController { private final TransferService service; public TransferController(TransferService service){this.service=service;} @PostMapping @PreAuthorize("hasAuthority('TRANSFER_CREATE')") public ApiResponse<TransferResponse> create(@Valid @RequestBody TransferCreateRequest r,@AuthenticationPrincipal UserDetails u){return ApiResponse.success("Transfer created successfully",service.create(r,u.getUsername()));} @GetMapping @PreAuthorize("hasAuthority('TRANSFER_READ')") public ApiResponse<Page<TransferResponse>> list(@RequestParam(required=false)StockTransferStatus status,@PageableDefault(size=20,sort="createdAt",direction=Sort.Direction.DESC)Pageable p){return ApiResponse.success("Transfers retrieved successfully",service.list(status,p));} @GetMapping("/{id}") @PreAuthorize("hasAuthority('TRANSFER_READ')") public ApiResponse<TransferResponse> get(@PathVariable UUID id){return ApiResponse.success("Transfer retrieved successfully",service.get(id));} @PostMapping("/{id}/approve") @PreAuthorize("hasAuthority('TRANSFER_APPROVE')") public ApiResponse<TransferResponse> approve(@PathVariable UUID id,@AuthenticationPrincipal UserDetails u){return ApiResponse.success("Transfer approved successfully",service.approve(id,u.getUsername()));} @PostMapping("/{id}/reject") @PreAuthorize("hasAuthority('TRANSFER_APPROVE')") public ApiResponse<TransferResponse> reject(@PathVariable UUID id,@Valid @RequestBody TransferActionRequest r,@AuthenticationPrincipal UserDetails u){return ApiResponse.success("Transfer rejected",service.reject(id,u.getUsername(),r));} @PostMapping("/{id}/pick") @PreAuthorize("hasAuthority('TRANSFER_DISPATCH')") public ApiResponse<TransferResponse> pick(@PathVariable UUID id,@AuthenticationPrincipal UserDetails u){return ApiResponse.success("Transfer picked successfully",service.pick(id,u.getUsername()));} @PostMapping("/{id}/dispatch") @PreAuthorize("hasAuthority('TRANSFER_DISPATCH')") public ApiResponse<TransferResponse> dispatch(@PathVariable UUID id,@AuthenticationPrincipal UserDetails u){return ApiResponse.success("Transfer dispatched successfully",service.dispatch(id,u.getUsername()));} @PostMapping("/{id}/receive") @PreAuthorize("hasAuthority('TRANSFER_RECEIVE')") public ApiResponse<TransferResponse> receive(@PathVariable UUID id,@AuthenticationPrincipal UserDetails u){return ApiResponse.success("Transfer received successfully",service.receive(id,u.getUsername()));} @PostMapping("/{id}/complete") @PreAuthorize("hasAuthority('TRANSFER_RECEIVE')") public ApiResponse<TransferResponse> complete(@PathVariable UUID id,@AuthenticationPrincipal UserDetails u){return ApiResponse.success("Transfer completed successfully",service.complete(id,u.getUsername()));} @PostMapping("/{id}/cancel") @PreAuthorize("hasAuthority('TRANSFER_CREATE')") public ApiResponse<TransferResponse> cancel(@PathVariable UUID id,@AuthenticationPrincipal UserDetails u){return ApiResponse.success("Transfer cancelled successfully",service.cancel(id,u.getUsername()));} }
